#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

ENV_FILE="${ISSUE680_STATE_FILE:-/private/tmp/spine-issue680-qualification.env}"
REPORT_PATH="${ISSUE680_REPORT_PATH:-/private/tmp/issue-680-mounted-filesystem-live-report.json}"
EXPECTED_PACKAGE_SHA256="e7367a5419e65c552ea7340404cb5241b2b8022c084fa5faa58086e089d8dc71"
WIZARD_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
REPORT_WRITER="$WIZARD_DIR/issue680_qualification_report.py"
umask 077

write_operator_report() {
  python3 "$REPORT_WRITER" \
    --state "$ENV_FILE" \
    --report "$REPORT_PATH" \
    --reason "$1"
}

die() {
  write_operator_report prerequisite_missing || true
  printf '  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2
  exit 1
}

require_uuid() {
  [[ "$2" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] || \
    die "$1 must be a lowercase canonical UUID"
}

require_safe_reference() {
  [[ -n "$2" && "$2" =~ ^[A-Za-z0-9._:-]+$ ]] || \
    die "$1 must be a non-secret opaque reference without paths or whitespace"
}

ask_status() {
  local key="$1" prompt="$2" value
  ask "$key" "$prompt [PASS/FAIL/NOT_VERIFIED]:"
  eval "value=\${$key}"
  value=$(printf '%s' "$value" | tr '[:lower:]' '[:upper:]')
  case "$value" in
    PASS|FAIL|NOT_VERIFIED) ;;
    *) die "$key must be PASS, FAIL, or NOT_VERIFIED" ;;
  esac
  printf -v "$key" '%s' "$value"
  write_env "$key" "$value"
}

file_sha256() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{print $1}'
  else
    die "sha256sum or shasum is required"
  fi
}

mount_fingerprint() {
  if command -v sha256sum >/dev/null 2>&1; then
    printf '%s' "$1" | sha256sum | awk '{print $1}'
  else
    printf '%s' "$1" | shasum -a 256 | awk '{print $1}'
  fi
}

if [[ "${1:-}" == "--describe" ]]; then
  printf '%s\n' \
    "1. Approved scope and ownership" \
    "2. Read-only target preflight" \
    "3. Baseline and containment" \
    "4. Streaming and size limits" \
    "5. Path-scoped rename" \
    "6. Unstable read quarantine" \
    "7. Mount interruption and recovery" \
    "8. Identity, sanitized evidence, and cleanup"
  exit 0
fi

banner "Spine issue #680 mounted-filesystem qualification"

stage "Approved scope and ownership"
say "Capture only non-secret identifiers. Share addresses and credentials never enter this wizard."
ask WORKSPACE_ID "Workspace UUID:"
require_uuid WORKSPACE_ID "$WORKSPACE_ID"
ask ENVIRONMENT_ID "Environment UUID:"
require_uuid ENVIRONMENT_ID "$ENVIRONMENT_ID"
ask CONNECTION_VERSION_ID "Provider Connection version UUID:"
require_uuid CONNECTION_VERSION_ID "$CONNECTION_VERSION_ID"
ask RESOURCE_SCOPE_REFERENCE "Opaque approved resource-scope reference:"
require_safe_reference RESOURCE_SCOPE_REFERENCE "$RESOURCE_SCOPE_REFERENCE"
ask DATA_OWNER_APPROVAL_REFERENCE "Opaque Data Owner approval reference:"
require_safe_reference DATA_OWNER_APPROVAL_REFERENCE "$DATA_OWNER_APPROVAL_REFERENCE"
ask PLATFORM_OPERATIONS_REFERENCE "Opaque Platform Operations change reference:"
require_safe_reference PLATFORM_OPERATIONS_REFERENCE "$PLATFORM_OPERATIONS_REFERENCE"
ask SECURITY_IDENTITY_REFERENCE "Opaque Security identity-binding reference:"
require_safe_reference SECURITY_IDENTITY_REFERENCE "$SECURITY_IDENTITY_REFERENCE"
for key in WORKSPACE_ID ENVIRONMENT_ID CONNECTION_VERSION_ID RESOURCE_SCOPE_REFERENCE \
  DATA_OWNER_APPROVAL_REFERENCE PLATFORM_OPERATIONS_REFERENCE SECURITY_IDENTITY_REFERENCE; do
  eval "value=\${$key}"
  write_env "$key" "$value"
done

stage "Read-only target preflight"
say "Platform Operations must stage the synthetic archive on the backend before this stage."
ask PACKAGE_PATH "Local path to issue-680-synthetic-v1.tar.gz:"
[[ -f "$PACKAGE_PATH" ]] || die "synthetic package is unavailable"
PACKAGE_SHA256=$(file_sha256 "$PACKAGE_PATH")
[[ "$PACKAGE_SHA256" == "$EXPECTED_PACKAGE_SHA256" ]] || die "synthetic package checksum mismatch"
write_env PACKAGE_SHA256 "$PACKAGE_SHA256"
ask QUALIFICATION_ROOT "Approved qualification leaf path:"
expected_root="/mnt/spine/sources/qualification/issue-680/$CONNECTION_VERSION_ID"
[[ "$QUALIFICATION_ROOT" == "$expected_root" ]] || die "qualification leaf is outside the approved namespace"
[[ -d "$QUALIFICATION_ROOT" ]] || die "approved qualification leaf is unavailable"
resolved_root=$(cd "$QUALIFICATION_ROOT" && pwd -P)
[[ "$resolved_root" == "$QUALIFICATION_ROOT" ]] || die "qualification leaf is not canonical"
write_env QUALIFICATION_ROOT "$QUALIFICATION_ROOT"
command -v findmnt >/dev/null 2>&1 || die "findmnt is required on the qualification host"
MOUNT_FACTS=$(findmnt -n -o FSTYPE,OPTIONS --target "$QUALIFICATION_ROOT")
[[ -n "$MOUNT_FACTS" ]] || die "mount facts are unavailable"
FILESYSTEM_TYPE=${MOUNT_FACTS%% *}
MOUNT_OPTIONS=${MOUNT_FACTS#* }
for required_option in ro nodev nosuid noexec; do
  [[ ",$MOUNT_OPTIONS," == *",$required_option,"* ]] || die "mount option $required_option is missing"
done
MOUNT_OPTION_FINGERPRINT=$(mount_fingerprint "$FILESYSTEM_TYPE $MOUNT_OPTIONS")
write_env FILESYSTEM_TYPE "$FILESYSTEM_TYPE"
write_env MOUNT_OPTION_FINGERPRINT "$MOUNT_OPTION_FINGERPRINT"
id spine-source-reader >/dev/null 2>&1 || die "spine-source-reader identity is unavailable"
READER_UID=$(id -u spine-source-reader)
READER_GID=$(id -g spine-source-reader)
[[ "$READER_UID" != "0" ]] || die "spine-source-reader must not be root"
write_env READER_UID "$READER_UID"
write_env READER_GID "$READER_GID"
ask WRITE_DENIAL_EVIDENCE_REFERENCE "Opaque reference proving source write authority is denied:"
require_safe_reference WRITE_DENIAL_EVIDENCE_REFERENCE "$WRITE_DENIAL_EVIDENCE_REFERENCE"
ask MOUNT_DENIAL_EVIDENCE_REFERENCE "Opaque reference proving mount authority is denied:"
require_safe_reference MOUNT_DENIAL_EVIDENCE_REFERENCE "$MOUNT_DENIAL_EVIDENCE_REFERENCE"
write_env WRITE_DENIAL_EVIDENCE_REFERENCE "$WRITE_DENIAL_EVIDENCE_REFERENCE"
write_env MOUNT_DENIAL_EVIDENCE_REFERENCE "$MOUNT_DENIAL_EVIDENCE_REFERENCE"
ask_status PREFLIGHT_STATUS "Preflight outcome"

stage "Baseline and containment"
say "Use the deployed MountedFilesystemReconciliationWorker.reconcile entry point as spine-source-reader."
step "Run one complete baseline reconciliation through the approved production composition."
step "Exercise invalid traversal references and observe rejection before source disclosure."
step "Confirm the packaged symlinks and FIFO are rejected and never followed or read."
pause "Press Enter after the deployment run and content-safe evidence are available."
ask BASELINE_RUN_REFERENCE "Opaque baseline run reference:"
require_safe_reference BASELINE_RUN_REFERENCE "$BASELINE_RUN_REFERENCE"
write_env BASELINE_RUN_REFERENCE "$BASELINE_RUN_REFERENCE"
ask_status CONTAINMENT_STATUS "Baseline and containment outcome"

stage "Streaming and size limits"
step "Through the same approved production composition, read the packaged chunk-boundary and exact-limit fixtures."
step "Confirm reads use the 64 KiB profile and the exact 32 MiB fixture is accepted."
step "Confirm the 32 MiB plus one byte fixture is rejected without canonical acceptance."
pause "Press Enter after bounded-read evidence is available."
ask LIMITS_RUN_REFERENCE "Opaque limits run reference:"
require_safe_reference LIMITS_RUN_REFERENCE "$LIMITS_RUN_REFERENCE"
write_env LIMITS_RUN_REFERENCE "$LIMITS_RUN_REFERENCE"
ask_status LIMITS_STATUS "Streaming and size-limit outcome"

stage "Path-scoped rename"
warn "The backend operator performs the synthetic rename. Spine must not mutate the source."
confirm "Has Platform Operations approved the rename step?" || die "rename approval is required"
step "Follow the rename phase in the package scenario plan on the backend."
step "Run a complete reconciliation through the approved production composition."
step "Confirm old-path absence plus a new observation, with no inode or checksum continuity claim."
pause "Press Enter after rename evidence is available."
ask RENAME_RUN_REFERENCE "Opaque rename run reference:"
require_safe_reference RENAME_RUN_REFERENCE "$RENAME_RUN_REFERENCE"
write_env RENAME_RUN_REFERENCE "$RENAME_RUN_REFERENCE"
ask_status RENAME_STATUS "Path-scoped rename outcome"

stage "Unstable read quarantine"
warn "The backend operator replaces only the designated synthetic candidate while Spine reads it."
confirm "Has Platform Operations approved the two-attempt unstable-read step?" || die "unstable-read approval is required"
step "Follow the unstable-read phase in the package scenario plan for both bounded attempts."
step "Confirm the item is quarantined after two attempts with no mixed-byte acceptance or absence effect."
pause "Press Enter after unstable-read evidence is available."
ask UNSTABLE_RUN_REFERENCE "Opaque unstable-read run reference:"
require_safe_reference UNSTABLE_RUN_REFERENCE "$UNSTABLE_RUN_REFERENCE"
write_env UNSTABLE_RUN_REFERENCE "$UNSTABLE_RUN_REFERENCE"
ask_status UNSTABLE_STATUS "Unstable-read outcome"

stage "Mount interruption and recovery"
warn "Only Platform Operations may interrupt or restore the mount. This wizard executes no mount command."
confirm "Has Platform Operations approved the interruption window?" || die "interruption approval is required"
step "Interrupt the qualification mount after the accepted baseline, then invoke reconciliation."
step "Confirm unavailable or incomplete state and zero deletion or tombstone authorization."
pause "Press Enter after interruption evidence is available."
ask OUTAGE_RUN_REFERENCE "Opaque interruption run reference:"
require_safe_reference OUTAGE_RUN_REFERENCE "$OUTAGE_RUN_REFERENCE"
write_env OUTAGE_RUN_REFERENCE "$OUTAGE_RUN_REFERENCE"
ask_status OUTAGE_STATUS "Mount-interruption outcome"
step "Restore the exact approved leaf and hold the corpus stable for two matching snapshots."
step "Run full recovery reconciliation and confirm one logical effect per revision."
step "Confirm the canonical retention anchor remained present throughout the outage."
pause "Press Enter after recovery evidence is available."
ask RECOVERY_RUN_REFERENCE "Opaque recovery run reference:"
require_safe_reference RECOVERY_RUN_REFERENCE "$RECOVERY_RUN_REFERENCE"
write_env RECOVERY_RUN_REFERENCE "$RECOVERY_RUN_REFERENCE"
ask_status RECOVERY_STATUS "Recovery reconciliation outcome"

stage "Identity, sanitized evidence, and cleanup"
say "Path-scoped identity is the mandatory baseline. Inode and checksum evidence cannot upgrade it."
BACKEND_FILE_ID_STATUS="NOT_CLAIMED"
BACKEND_IDENTITY_EVIDENCE_REFERENCE="none"
write_env BACKEND_FILE_ID_STATUS "$BACKEND_FILE_ID_STATUS"
write_env BACKEND_IDENTITY_EVIDENCE_REFERENCE "$BACKEND_IDENTITY_EVIDENCE_REFERENCE"
ask_status IDENTITY_STATUS "Identity qualification outcome"
warn "Cleanup removes only the synthetic backend corpus and qualification mount after evidence capture."
confirm "Has the Data Owner approved qualification cleanup?" || die "cleanup approval is required"
step "Platform Operations removes the qualification mount and synthetic backend files outside Spine."
step "Do not remove imported originals, Source Revisions, tombstones, or lifecycle evidence."
pause "Press Enter after Platform Operations records cleanup completion."
ask CLEANUP_EVIDENCE_REFERENCE "Opaque cleanup evidence reference:"
require_safe_reference CLEANUP_EVIDENCE_REFERENCE "$CLEANUP_EVIDENCE_REFERENCE"
write_env CLEANUP_EVIDENCE_REFERENCE "$CLEANUP_EVIDENCE_REFERENCE"
ask_status CLEANUP_STATUS "Cleanup outcome"

write_operator_report independent_evidence_review_required
chmod 600 "$ENV_FILE" "$REPORT_PATH"
say "Sanitized report: $REPORT_PATH"
say "Private resumable state: $ENV_FILE"
say "The operator report remains NOT_VERIFIED until independent evidence review."

finish
